import { createBoxOffice, type BoxOfficeOptions } from "./boxOffice";

const MINUTE = 60_000;

function setup(overrides: Partial<BoxOfficeOptions> = {}) {
  const clock = { time: 1_000_000 };
  const office = createBoxOffice({
    sections: [
      { id: "PARKETT", capacity: 10, priceCents: 4990 },
      { id: "BALKON", capacity: 5, priceCents: 3000 },
    ],
    holdMinutes: 15,
    maxTicketsPerCustomer: 6,
    now: () => clock.time,
    ...overrides,
  });
  return { office, clock };
}

function codeOf(fn: () => unknown): string | undefined {
  try {
    fn();
  } catch (error) {
    return error instanceof BoxOfficeError ? error.code : `not a BoxOfficeError: ${error}`;
  }
  return undefined;
}

describe("availability", () => {
  test("a fresh section has its full capacity available", () => {
    const { office } = setup();
    expect(office.available("PARKETT")).toBe(10);
  });
});
EOF
