export function createBoxOffice(options: BoxOfficeOptions): BoxOffice {
  const holds: Hold[] = [];

  function sectionOf(sectionId: string): SectionConfig {
    const section = options.sections.find((s) => s.id === sectionId);
    if (!section) throw new BoxOfficeError("UNKNOWN_SECTION", `Unknown section ${sectionId}`);
    return section;
  }

  return {
    hold(customerId, sectionId, quantity) {
      sectionOf(sectionId);
      const hold = {
        holdId: "H1",
        customerId,
        sectionId,
        quantity,
        expiresAt: options.now() + options.holdMinutes * 60_000,
      };
      holds.push(hold);
      return hold;
    },
    confirm() {
      throw new Error("Not implemented");
    },
    release() {
      throw new Error("Not implemented");
    },
    cancelOrder() {
      throw new Error("Not implemented");
    },
    available(sectionId) {
      const section = sectionOf(sectionId);
      const held = holds.filter((h) => h.sectionId === sectionId).reduce((sum, h) => sum + h.quantity, 0);
      return section.capacity - held;
    },
  };
}
EOF
